import{_ as t}from"./chunks/eye.BRl0ZGNz.js";import{_ as o}from"./chunks/trash.D6Oim2A3.js";import{_ as n}from"./chunks/more-horizontal.C1CblXWl.js";import{_ as s,c as r,o as l,ag as i}from"./chunks/framework.DZ_cNctr.js";const a="/docs/icons/eye-off.svg",v=JSON.parse('{"title":"Annotations — Find Nuclei Viewer","description":"Draw, select, classify, and bulk-edit regions of interest on OME-Zarr images. Freehand lasso selection, annotation templates, group translate, and bulk template / color / delete actions.","frontmatter":{"title":"Annotations — Find Nuclei Viewer","description":"Draw, select, classify, and bulk-edit regions of interest on OME-Zarr images. Freehand lasso selection, annotation templates, group translate, and bulk template / color / delete actions."},"headers":[],"relativePath":"guides/annotations.md","filePath":"guides/annotations.md"}'),d={name:"guides/annotations.md"};function c(h,e,p,u,g,m){return l(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h1><p>Draw, classify, and organise regions of interest on your image. Annotations work at full-image resolution, persist with your saved view, and survive reloads.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-overview.png</code> — Wide shot of the viewer with a handful of annotations drawn on a WSI, the Annotations tab open in the sidebar showing the grouped list. </div><h2 id="drawing" tabindex="-1">Drawing <a class="header-anchor" href="#drawing" aria-label="Permalink to &quot;Drawing&quot;">​</a></h2><p>Pick a tool from the toolbar above the image:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Shortcut</th><th>Use for</th></tr></thead><tbody><tr><td>Polygon</td><td><code>P</code></td><td>Closed regions — tumour, stroma, necrosis</td></tr><tr><td>Line</td><td><code>L</code></td><td>Open paths, trajectories</td></tr><tr><td>Distance</td><td><code>D</code></td><td>Measurements between two points</td></tr><tr><td>Point</td><td><code>B</code></td><td>Single-coordinate markers</td></tr><tr><td>Cut hole</td><td><code>K</code></td><td>Subtract a region from an existing polygon</td></tr></tbody></table><h3 id="polygon-—-two-ways-to-draw" tabindex="-1">Polygon — two ways to draw <a class="header-anchor" href="#polygon-—-two-ways-to-draw" aria-label="Permalink to &quot;Polygon — two ways to draw&quot;">​</a></h3><ul><li><strong>Click-to-place</strong>: click each vertex, double-click to close. Best for precise outlines with a few vertices.</li><li><strong>Freehand</strong>: press and drag. The path is simplified on release (Douglas-Peucker) so a scribble becomes a clean polygon. Best for organic shapes.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-draw-polygon.png</code> — Mid-draw polygon on tissue — a few placed vertices with the preview line extending to the cursor. </div><h3 id="cut-hole" tabindex="-1">Cut hole <a class="header-anchor" href="#cut-hole" aria-label="Permalink to &quot;Cut hole&quot;">​</a></h3><p>Select a polygon first, then activate Cut hole. Any closed shape you draw inside is subtracted — good for excluding a lumen from a tissue region or excluding necrosis from tumour.</p><h2 id="selecting" tabindex="-1">Selecting <a class="header-anchor" href="#selecting" aria-label="Permalink to &quot;Selecting&quot;">​</a></h2><p>The <strong>Select</strong> tool (<code>V</code>) is the pointer you edit with.</p><h3 id="single-select" tabindex="-1">Single select <a class="header-anchor" href="#single-select" aria-label="Permalink to &quot;Single select&quot;">​</a></h3><ul><li><strong>Click a shape</strong> on canvas, or click a row in the annotation list.</li><li>The detail panel expands below the selected row (Notes, Key-values, Template).</li><li>Canvas: vertex handles appear at every corner; drag them to reshape.</li></ul><h3 id="multi-select-—-list" tabindex="-1">Multi-select — list <a class="header-anchor" href="#multi-select-—-list" aria-label="Permalink to &quot;Multi-select — list&quot;">​</a></h3><ul><li><strong>Cmd/Ctrl + click</strong> a row: toggle it into the selection.</li><li><strong>Shift + click</strong> a row: range-select from the current anchor to the new row, across groups in display order.</li><li><strong>Click empty space</strong> in the annotation panel (or press <code>Esc</code>): clear the whole selection.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-multiselect-list.png</code> — Annotation list with several rows highlighted green, the bulk action bar visible at the top showing &quot;5 selected&quot;. </div><h3 id="multi-select-—-canvas-lasso" tabindex="-1">Multi-select — canvas lasso <a class="header-anchor" href="#multi-select-—-canvas-lasso" aria-label="Permalink to &quot;Multi-select — canvas lasso&quot;">​</a></h3><p>Switch to the Select tool. Anywhere the cursor lands on empty canvas <strong>or</strong> on a non-selected annotation, press and drag to draw a freehand lasso. On release, every annotation that sits <strong>fully inside</strong> the lasso joins the selection.</p><table tabindex="0"><thead><tr><th>Modifier</th><th>Effect</th></tr></thead><tbody><tr><td>(none)</td><td>Replace selection</td></tr><tr><td>Shift + drag</td><td>Add lassoed shapes to the existing selection</td></tr><tr><td>Alt + drag</td><td>Remove lassoed shapes from the selection</td></tr></tbody></table><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-lasso.png</code> — A primary-green lasso path drawn around a cluster of cells, mid-drag (loop not yet closed). </div><p>&quot;Fully inside&quot; means <strong>every vertex</strong> of the annotation is inside your loop — shapes that clip the edge are excluded. If you lasso <em>inside</em> a large region (e.g. a tissue outline), that big region is not selected — it&#39;s not fully enclosed by your smaller loop.</p><h3 id="visual-feedback" tabindex="-1">Visual feedback <a class="header-anchor" href="#visual-feedback" aria-label="Permalink to &quot;Visual feedback&quot;">​</a></h3><ul><li><strong>Selected</strong>: a green halo around the shape on canvas, and a green left border on the list row.</li><li><strong>Active</strong>: the one annotation whose detail panel is open. In single-select it&#39;s the same shape; in multi-select it&#39;s the last one you clicked. Vertex handles appear only on the active annotation in single-select; multi-select hides handles so every selected shape reads as equal.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-halo.png</code> — Canvas close-up of 3 selected polygons with the primary-green halo visible around each. </div><h2 id="bulk-actions" tabindex="-1">Bulk actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk actions&quot;">​</a></h2><p>When 2+ annotations are selected, a bulk action bar appears at the top of the list:</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-bulk-bar.png</code> — The bulk action bar: &quot;5 selected · Template dropdown · Color · <img src="'+t+'" class="fn-icon" alt="show"> <img src="'+a+'" class="fn-icon" alt="hide"> <img src="'+o+'" class="fn-icon" alt="delete">&quot;. </div><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>Template dropdown</td><td>Apply a template to every selected annotation (color + class + label substitution)</td></tr><tr><td>Color</td><td>Pick a color for every selected annotation at once</td></tr><tr><td><img src="'+t+'" class="fn-icon" alt="show"> / <img src="'+a+'" class="fn-icon" alt="hide"></td><td>Show / hide every selected annotation</td></tr><tr><td><img src="'+o+'" class="fn-icon" alt="delete"></td><td>Delete every selected annotation (with confirmation)</td></tr></tbody></table><p>All bulk operations are batched — one <strong>Cmd+Z</strong> reverts the whole action, not each annotation individually.</p><h3 id="group-translate" tabindex="-1">Group translate <a class="header-anchor" href="#group-translate" aria-label="Permalink to &quot;Group translate&quot;">​</a></h3><p>Drag the body of any selected annotation and <strong>the whole group moves</strong> together. Arrow keys work the same way: <code>←→↑↓</code> nudges every selected shape by 1 pixel, <code>Shift + arrow</code> by 10 pixels.</p><h3 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>With selection</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>Clear selection</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>Delete (with confirmation if 2+ selected)</td></tr><tr><td>Arrow keys</td><td>Nudge group by 1 px</td></tr><tr><td><code>Shift</code> + arrow</td><td>Nudge group by 10 px</td></tr></tbody></table><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>Templates bundle a color, class, and other metadata into a single click. When you apply a template, the annotation gets the template&#39;s color, its <code>class</code> key-value, and — if the label contains the previous template&#39;s name — the name is substituted in place (<code>Tumor 1</code> → <code>Stroma 1</code>).</p><h3 id="picking-a-template-while-drawing" tabindex="-1">Picking a template while drawing <a class="header-anchor" href="#picking-a-template-while-drawing" aria-label="Permalink to &quot;Picking a template while drawing&quot;">​</a></h3><p>Open the Templates manager from the Annotations toolbar. While any drawing tool is active, an on-canvas chip row shows the available templates — click one to set it as active. Every annotation you create next inherits that template.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-template-picker.png</code> — On-canvas template chip row with Tumor / Stroma / Necrosis / Immune etc., one highlighted as active. </div><p>Keyboard: <code>Alt + 1</code> through <code>Alt + 9</code> select templates by shortcut slot.</p><h3 id="changing-a-template-after-drawing" tabindex="-1">Changing a template after drawing <a class="header-anchor" href="#changing-a-template-after-drawing" aria-label="Permalink to &quot;Changing a template after drawing&quot;">​</a></h3><p>Click the annotation&#39;s color swatch. The popover opens with a Template dropdown at the top:</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-template-swatch.png</code> — The swatch popover open on an annotation, showing: Template dropdown, Opacity, Render (FILL/CONTOUR), Presets grid, Custom hex/RGB. </div><p>Pick a different template and the annotation&#39;s color, class, and label update together. The list re-orders into the new class group and the canvas smoothly zooms so you don&#39;t lose track.</p><h3 id="bulk-template-assignment" tabindex="-1">Bulk template assignment <a class="header-anchor" href="#bulk-template-assignment" aria-label="Permalink to &quot;Bulk template assignment&quot;">​</a></h3><p>Select several annotations (list or lasso), then pick a template from the bulk action bar&#39;s Template dropdown. Every selected annotation is reclassified in one undoable step.</p><h2 id="grouping-sorting" tabindex="-1">Grouping &amp; sorting <a class="header-anchor" href="#grouping-sorting" aria-label="Permalink to &quot;Grouping &amp; sorting&quot;">​</a></h2><p>The annotation list groups by <code>class</code> by default. Click <strong>Group By</strong> on the toolbar to group by any other key-value field, or to disable grouping.</p><p>Within each group, annotations sort by their label using natural numeric comparison, so <code>Tumor 1, Tumor 2, …, Tumor 10</code> reads in numeric order (not lexicographic <code>Tumor 1, Tumor 10, Tumor 2</code>).</p><p>Previous/Next navigation walks the same sorted order the list displays, so pressing Next moves you through the list the way you&#39;d expect.</p><h2 id="global-display-controls" tabindex="-1">Global display controls <a class="header-anchor" href="#global-display-controls" aria-label="Permalink to &quot;Global display controls&quot;">​</a></h2><p>The toolbar&#39;s <img src="'+n+'" class="fn-icon" alt="more"> kebab menu holds global bulk actions that apply to every annotation (not just the selected ones):</p><ul><li><strong>Show all</strong> / <strong>Hide all</strong> — toggle visibility for the whole list.</li><li><strong>Turn fill on</strong> / <strong>off</strong> — apply to every polygon.</li><li><strong>Turn contour on</strong> / <strong>off</strong> — apply to every polygon.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-global-kebab.png</code> — The kebab menu open, showing Show all / Hide all / Turn fill off / Turn contour off items. </div><h2 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h2><p>Two ways to set a color:</p><ul><li><strong>Picker presets</strong>: open the swatch popover. The Presets grid shows 16 curated colors — RGB primaries on top, muted / perceptually-nicer variants on the bottom row. One click applies.</li><li><strong>Custom</strong>: type a hex value (<code>#FF00AA</code>) or drive the three RGB number inputs directly. Synced bidirectionally. The &quot;More colors…&quot; button opens the OS-native picker for free-form choice or eyedropper (Chrome / Edge).</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>annotations-colorpicker.png</code> — ColorPicker popover with presets grid, hex input, RGB inputs, &quot;More colors…&quot; button. </div><p>Channels use a fluorescence-specific palette (DAPI blue, GFP green, Cy5 red, etc.); labels and annotations share a general palette. Picking &quot;Green&quot; for an annotation gets the same hex as &quot;GFP&quot; on a channel, so a color swap affects both the display and any reference you&#39;ve built on top.</p><h2 id="details-—-notes-tags-key-values" tabindex="-1">Details — Notes, Tags, Key-values <a class="header-anchor" href="#details-—-notes-tags-key-values" aria-label="Permalink to &quot;Details — Notes, Tags, Key-values&quot;">​</a></h2><p>With one annotation active, the detail panel below the row exposes:</p><ul><li><strong>Notes</strong> — free-form text.</li><li><strong>Key-values</strong> — structured metadata rows. <code>class</code> is reserved for templates; other keys are yours to invent (<code>grade</code>, <code>reviewer</code>, <code>date-checked</code>, etc.).</li></ul><p>Notes and key-values survive reloads (saved to IndexedDB) and round-trip through GeoJSON export / import.</p><h2 id="import-and-export" tabindex="-1">Import and export <a class="header-anchor" href="#import-and-export" aria-label="Permalink to &quot;Import and export&quot;">​</a></h2><ul><li><strong>Import GeoJSON</strong> — bring in annotations drawn elsewhere.</li><li><strong>Export GeoJSON</strong> — the same format that QGIS, QuPath, napari, and Fiji understand.</li><li><strong>Export CSV</strong> — one row per annotation with label, class, measurements, centroid.</li></ul><h2 id="keyboard-shortcut-summary" tabindex="-1">Keyboard shortcut summary <a class="header-anchor" href="#keyboard-shortcut-summary" aria-label="Permalink to &quot;Keyboard shortcut summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>V</code></td><td>Select tool</td></tr><tr><td><code>P</code> / <code>L</code> / <code>D</code> / <code>B</code> / <code>K</code></td><td>Polygon / Line / Distance / Point / Cut-hole</td></tr><tr><td><code>Esc</code></td><td>Cancel current draw OR clear selection</td></tr><tr><td><code>Space</code> (hold)</td><td>Temporary Pan (while drawing)</td></tr><tr><td><code>Cmd/Ctrl + Z</code> / <code>Shift</code></td><td>Undo / Redo</td></tr><tr><td><code>Cmd/Ctrl + C</code> / <code>V</code></td><td>Copy / Paste annotation</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>Delete selected (with confirm if 2+)</td></tr><tr><td>Arrow keys</td><td>Nudge selected by 1 px</td></tr><tr><td><code>Shift</code> + arrow</td><td>Nudge selected by 10 px</td></tr><tr><td><code>Alt + 1</code>…<code>9</code></td><td>Select template slot</td></tr></tbody></table><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./sharing.html">Sharing Views</a> — annotations are saved in the URL state and restored on reload</li><li><a href="./hcs-plates.html">HCS Plates</a> — annotations work per-field in plate layouts</li><li><a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a> — color segmentation labels by per-object measurements</li></ul>',70)])])}const k=s(d,[["render",c]]);export{v as __pageData,k as default};
